 16	import com.fasterxml.jackson.databind.ObjectMapper;
 17	import java.net.HttpURLConnection;
 18	import java.net.URL;
 19	import java.nio.charset.StandardCharsets;
 20	
 21	public class TransLogAdapter implements ShippingCarrier {
 22	    private final String baseUrl;
 23	    private static final int TIMEOUT_MS = 2000;
 24	    private final ObjectMapper mapper = new ObjectMapper();
 25	
 26	    public TransLogAdapter(String baseUrl) {
 27	        this.baseUrl = baseUrl;
 28	    }
 29	
 30	    @Override
 31	    public ShippingQuote getQuote(String zipCode, Double weightGrams) {
 32	        return getQuoteWithService(zipCode, weightGrams, "STD");
 33	    }
 34	
 35	    public ShippingQuote getQuoteWithService(String zipCode, Double weightGrams, String service) {
 36	        try {
 37	            String url = String.format("%s/v2/quote?zip=%s&weight_g=%d&service=%s",
 38	                baseUrl, zipCode, weightGrams.intValue(), service);
 39	
 40	            HttpURLConnection conn = (HttpURLConnection) new URL(url).openConnection();
 41	            conn.setConnectTimeout(TIMEOUT_MS);
 42	            conn.setReadTimeout(TIMEOUT_MS);
 43	            conn.setRequestMethod("GET");
 44	
 45	            if (conn.getResponseCode() == 200) {
 46	                String response = new String(conn.getInputStream().readAllBytes(), StandardCharsets.UTF_8);
 47	                return mapper.readValue(response, ShippingQuote.class);
 48	            }
 49	
 50	            ShippingQuote quote = new ShippingQuote();
 51	            quote.error = "CARRIER_UNAVAILABLE";
 52	            return quote;
 53	
 54	        } catch (Exception e) {
 55	            ShippingQuote quote = new ShippingQuote();
 56	            quote.error = "CARRIER_UNAVAILABLE";
 57	            return quote;
 58	        }
 59	    }
 60	}
