 10	public class CheckoutService {
 11	    private final ProductRepository productRepo;
 12	    private final OrderService orderService;
 13	
 14	    public CheckoutService(ProductRepository productRepo, OrderService orderService) {
 15	        this.productRepo = productRepo;
 16	        this.orderService = orderService;
 17	    }
 18	
 19	    public OrderSummary calculateSummary(CheckoutRequest request) throws CheckoutException {
 20	        validateRequest(request);
 21	
 22	        Double productsSubtotal = calculateProductsSubtotal(request.items);
 23	
 24	        ShippingInfo shippingInfo = calculateShipping(request, productsSubtotal);
 25	        Double shippingCost = shippingInfo.cost;
 26	        Integer deliveryDays = shippingInfo.days;
 27	
 28	        ClubBenefitsStrategy clubBenefits = ClubFactory.create(request.clubTier);
 29	        Double shippingCostForDiscount = shippingCost;
 30	        if (clubBenefits.freeShipping(request.shippingMethod.name())) {
 31	            shippingCostForDiscount = 0.0;
 32	        }
 33	
 34	        Double couponDiscount = calculateCouponDiscount(request, productsSubtotal, shippingCostForDiscount);
 35	        couponDiscount = applyCouponCap(couponDiscount, productsSubtotal);
 36	
 37	        Double insurance = calculateInsurance(productsSubtotal, request.region);
 38	
 39	        Double adjustedShippingCost = shippingCost;
 40	        if (clubBenefits.freeShipping(request.shippingMethod.name())) {
 41	            adjustedShippingCost = 0.0;
 42	        }
 43	
 44	        Double subtotalBeforePayment = productsSubtotal - couponDiscount + adjustedShippingCost + insurance;
 45	        Double paymentAdjustment = calculatePaymentAdjustment(request, subtotalBeforePayment);
 46	
 47	        Double finalTotal = Money.round(subtotalBeforePayment + paymentAdjustment);
 48	
 49	        Integer installments = request.installments != null ? request.installments : 1;
 50	        Double installmentAmount = calculateInstallmentAmount(finalTotal, installments);
 51	
 52	        Double nextPurchaseCredit = calculateCredit(productsSubtotal, clubBenefits);
 53	
 54	        Boolean gift = clubBenefits.giftForLargeOrder(productsSubtotal);
 55	
 56	        return new OrderSummary(
 57	            productsSubtotal,
 58	            couponDiscount,
 59	            adjustedShippingCost,
 60	            deliveryDays,
 61	            insurance,
 62	            paymentAdjustment,
 63	            finalTotal,
 64	            installments,
 65	            installmentAmount,
 66	            nextPurchaseCredit,
 67	            gift
 68	        );
 69	    }
 70	
 71	    private void validateRequest(CheckoutRequest request) throws CheckoutException {
 72	        if (request.items == null || request.items.isEmpty()) {
 73	            throw new CheckoutException("INVALID_ORDER");
 74	        }
 75	
 76	        Set<String> skus = new HashSet<>();
 77	        for (OrderItem item : request.items) {
 78	            if (item.sku == null || item.sku.isEmpty()) {
 79	                throw new CheckoutException("INVALID_ORDER");
 80	            }
 81	            if (item.quantity == null || item.quantity <= 0) {
 82	                throw new CheckoutException("INVALID_ORDER");
 83	            }
 84	            if (skus.contains(item.sku)) {
 85	                throw new CheckoutException("INVALID_ORDER");
 86	            }
 87	            skus.add(item.sku);
 88	        }
 89	
 90	        if (request.customer == null || request.customer.cpf == null || request.customer.email == null) {
 91	            throw new CheckoutException("INVALID_ORDER");
 92	        }
 93	
 94	        for (OrderItem item : request.items) {
 95	            Product product = productRepo.findBySku(item.sku);
 96	            if (product == null) {
 97	                throw new CheckoutException("UNKNOWN_PRODUCT");
 98	            }
 99	            if (product.discontinued) {
100	                throw new CheckoutException("PRODUCT_DISCONTINUED");
101	            }
102	            if (product.stock < item.quantity) {
103	                throw new CheckoutException("INSUFFICIENT_STOCK");
104	            }
105	        }
106	
107	        if (request.clubTier == null) {
108	            throw new CheckoutException("INVALID_CLUB_TIER");
109	        }
110	
111	        if (request.region == null) {
112	            throw new CheckoutException("INVALID_REGION");
113	        }
114	
115	        if (request.zipCode == null || request.zipCode.length() != 8) {
116	            throw new CheckoutException("INVALID_ZIP_CODE");
117	        }
118	
119	        if (request.shippingMethod == null) {
120	            throw new CheckoutException("INVALID_SHIPPING_METHOD");
121	        }
122	
123	        if (request.paymentMethod == null) {
124	            throw new CheckoutException("INVALID_PAYMENT_METHOD");
125	        }
126	
127	        if (request.installments == null) {
128	            request.installments = 1;
129	        }
130	
131	        PaymentStrategy paymentStrategy = PaymentFactory.create(request.paymentMethod);
132	        if (!paymentStrategy.isApplicable(0.0, request.installments)) {
133	            throw new CheckoutException("INVALID_INSTALLMENTS");
134	        }
135	
136	        validateCoupon(request);
137	        validateShippingMethod(request);
138	    }
139	
140	    private void validateCoupon(CheckoutRequest request) throws CheckoutException {
141	        if (request.coupon != null && !request.coupon.isEmpty()) {
142	            CouponFactory factory = new CouponFactory(orderService.getOrderRepo());
143	            if (!factory.isValidCoupon(request.coupon)) {
144	                throw new CheckoutException("INVALID_COUPON");
145	            }
146	        }
147	    }
148	
149	    private void validateShippingMethod(CheckoutRequest request) throws CheckoutException {
150	        if (request.shippingMethod == ShippingMethod.COURIER) {
151	            Double totalWeight = calculateTotalWeight(request.items);
152	            if (totalWeight > 5.0) {
153	                throw new CheckoutException("SHIPPING_METHOD_UNAVAILABLE");
154	            }
155	        }
156	
157	        if (request.shippingMethod == ShippingMethod.ECONOMY || request.shippingMethod == ShippingMethod.EXPRESS) {
158	            String translogUrl = System.getenv("TRANSLOG_URL");
159	            if (translogUrl == null || translogUrl.isEmpty()) {
160	                throw new CheckoutException("CARRIER_UNAVAILABLE");
161	            }
162	
163	            try {
164	                ShippingCarrier carrier = new com.loja.shipping.TransLogAdapter(translogUrl);
165	                Double weightGrams = calculateTotalWeight(request.items) * 1000;
166	                ShippingQuote quote = carrier.getQuote(request.zipCode, weightGrams);
167	
168	                if (quote.error != null) {
169	                    if ("ZIP_NOT_SERVED".equals(quote.error)) {
170	                        throw new CheckoutException("SHIPPING_METHOD_UNAVAILABLE");
171	                    }
172	                    throw new CheckoutException("CARRIER_UNAVAILABLE");
173	                }
174	            } catch (CheckoutException e) {
175	                throw e;
176	            } catch (Exception e) {
177	                throw new CheckoutException("CARRIER_UNAVAILABLE");
178	            }
179	        }
180	    }
181	
182	    private Double calculateProductsSubtotal(List<OrderItem> items) {
183	        Double subtotal = 0.0;
184	        for (OrderItem item : items) {
185	            Product product = productRepo.findBySku(item.sku);
186	            if (product != null) {
187	                subtotal += product.price * item.quantity;
188	            }
189	        }
190	        return Money.round(subtotal);
191	    }
192	
193	    private Double calculateCouponDiscount(CheckoutRequest request, Double productsSubtotal, Double shippingCost) throws CheckoutException {
194	        if (request.coupon == null || request.coupon.isEmpty()) {
195	            return 0.0;
196	        }
197	
198	        CouponFactory factory = new CouponFactory(orderService.getOrderRepo());
199	        CouponStrategy strategy = factory.create(request.coupon);
200	
201	        if (strategy == null) {
202	            throw new CheckoutException("INVALID_COUPON");
203	        }
204	
205	        ProductProvider provider = sku -> productRepo.findBySku(sku);
206	        if (!strategy.isApplicable(request.customer.cpf, productsSubtotal, request.items, request.shippingMethod, provider)) {
207	            throw new CheckoutException("COUPON_NOT_APPLICABLE");
208	        }
209	
210	        if ("FREESHIPPING".equals(request.coupon)) {
211	            return Money.round(shippingCost);
212	        }
213	
214	        Double discount = strategy.calculateDiscount(productsSubtotal, request.items, provider);
215	        return discount != null ? discount : 0.0;
216	    }
217	
218	    private Double applyCouponCap(Double discount, Double productsSubtotal) {
219	        Double maxDiscount = Money.round(productsSubtotal * 0.30);
220	        if (discount > maxDiscount) {
221	            return maxDiscount;
222	        }
223	        return discount;
224	    }
225	
226	    private ShippingInfo calculateShipping(CheckoutRequest request, Double productsSubtotal) throws CheckoutException {
227	        switch (request.shippingMethod) {
228	            case STORE_PICKUP:
229	                return new ShippingInfo(0.0, 1);
230	            case COURIER:
231	                return new ShippingInfo(18.0, 0);
232	            case ECONOMY, EXPRESS:
233	                return getTranslogShipping(request);
234	        }
235	        throw new CheckoutException("INVALID_SHIPPING_METHOD");
236	    }
237	
238	    private ShippingInfo getTranslogShipping(CheckoutRequest request) throws CheckoutException {
239	        String translogUrl = System.getenv("TRANSLOG_URL");
240	        com.loja.shipping.TransLogAdapter adapter = new com.loja.shipping.TransLogAdapter(translogUrl);
241	
242	        Double weightGrams = calculateTotalWeight(request.items) * 1000;
243	        String service = request.shippingMethod == ShippingMethod.ECONOMY ? "STD" : "EXP";
244	
245	        ShippingQuote quote = adapter.getQuoteWithService(request.zipCode, weightGrams, service);
246	
247	        if (quote.error != null) {
248	            throw new CheckoutException("SHIPPING_METHOD_UNAVAILABLE");
249	        }
250	
251	        Double shippingCost = Money.round(quote.priceCents / 100.0);
252	        Integer deliveryDays = (int) Math.ceil(quote.etaHours / 24.0);
253	
254	        int extraDays = getExtraDaysForRegion(request.region);
255	        deliveryDays += extraDays;
256	
257	        return new ShippingInfo(shippingCost, deliveryDays);
258	    }
259	
260	    private int getExtraDaysForRegion(Region region) {
261	        return switch (region) {
262	            case NORTH -> 3;
263	            case NORTHEAST -> 2;
264	            default -> 0;
265	        };
266	    }
267	
268	    private Double calculateInsurance(Double productsSubtotal, Region region) {
269	        Double percentage = getInsurancePercentage(region);
270	        Double insurance = Money.round(productsSubtotal * percentage);
271	
272	        Double limit = getInsuranceLimit(region);
273	        if (limit != null && insurance > limit) {
274	            insurance = limit;
275	        }
276	
277	        return insurance;
278	    }
279	
280	    private Double getInsurancePercentage(Region region) {
281	        return switch (region) {
282	            case SOUTHEAST, SOUTH -> 0.01;
283	            case MIDWEST -> 0.015;
284	            case NORTH -> 0.025;
285	            case NORTHEAST -> 0.02;
286	        };
287	    }
288	
289	    private Double getInsuranceLimit(Region region) {
290	        return switch (region) {
291	            case NORTH, NORTHEAST -> 30.0;
292	            default -> null;
293	        };
294	    }
295	
296	    private Double calculatePaymentAdjustment(CheckoutRequest request, Double subtotal) throws CheckoutException {
297	        PaymentStrategy strategy = PaymentFactory.create(request.paymentMethod);
298	
299	        Integer installments = request.installments != null ? request.installments : 1;
300	
301	        if (!strategy.isApplicable(subtotal, installments)) {
302	            throw new CheckoutException("PAYMENT_METHOD_UNAVAILABLE");
303	        }
304	
305	        if (request.paymentMethod == PaymentMethod.PIX && request.coupon != null) {
306	            return 0.0;
307	        }
308	
309	        return strategy.calculateAdjustment(subtotal, installments);
310	    }
311	
312	    private Double calculateInstallmentAmount(Double finalTotal, Integer installments) {
313	        return Money.round(finalTotal / installments);
314	    }
315	
316	    private Double calculateCredit(Double productsSubtotal, ClubBenefitsStrategy benefits) {
317	        return Money.round(productsSubtotal * benefits.getCreditPercentage());
318	    }
319	
320	    private Double calculateTotalWeight(List<OrderItem> items) {
321	        Double weight = 0.0;
322	        for (OrderItem item : items) {
323	            Product product = productRepo.findBySku(item.sku);
324	            if (product != null) {
325	                weight += product.weightKg * item.quantity;
326	            }
327	        }
328	        return weight;
329	    }
330	
331	    private static class ShippingInfo {
332	        Double cost;
333	        Integer days;
334	
335	        ShippingInfo(Double cost, Integer days) {
336	            this.cost = cost;
337	            this.days = days;
338	        }
339	    }
340	}

