238	    private ShippingInfo getTranslogShipping(CheckoutRequest request) throws CheckoutException {
239	        String translogUrl = System.getenv("TRANSLOG_URL");
240	        com.loja.shipping.TransLogAdapter adapter = new com.loja.shipping.TransLogAdapter(translogUrl);
241	
242	        Double weightGrams = calculateTotalWeight(request.items) * 1000;
243	        String service = request.shippingMethod == ShippingMethod.ECONOMY ? "STD" : "EXP";
244	
245	        ShippingQuote quote = adapter.getQuoteWithService(request.zipCode, weightGrams, service);
246	
247	        if (quote.error != null) {
248	            throw new CheckoutException("SHIPPING_METHOD_UNAVAILABLE");
249	        }
250	
251	        Double shippingCost = Money.round(quote.priceCents / 100.0);
252	        Integer deliveryDays = (int) Math.ceil(quote.etaHours / 24.0);
253	
254	        int extraDays = getExtraDaysForRegion(request.region);
255	        deliveryDays += extraDays;
256	
257	        return new ShippingInfo(shippingCost, deliveryDays);
258	    }
